	sections = {
		{
			title = "Résumé",
			text = [=[La montagnarde Pebblebitty détient la clé de la porte verrouillée qui mène de {link:stranglethorn-vale}la Vallée{/link} des rois vers la {link:searing-gorge}Gorge des Vents brûlants{/link}. Elle ne l'ouvre pas à quiconque se contente de demander. Elle veut la preuve qu'un voyageur peut survivre à ce qui attend au-delà, et c'est un juge sévère. La grande bête {link:margol-the-rager}Margol{/link} l'Enragé porta autrefois dans sa corne la tête brisée de sa hache, et elle avait espéré la tuer elle-même.]=],
