Translate("frFR", "stonesplinter-troggs", {
	title = "Troggs Brisepierre",
	aliases = { "Brisepierre", "troggs Brisepierre", "tribu Brisepierre" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Brisepierre sont les {link:troggs}troggs{/link} du {link:loch-modan}Loch Modan{/link}. Ils tirent leur nom de {link:stranglethorn-vale}la Vallée{/link} des Brisepierre, au sud-ouest, et ils sont le plus grand danger auquel {link:the-loch}le Loch{/link} fait face. Aucune chronique ne dit quand ils remontèrent pour la première fois des profondeurs en ce lieu.]=],
		},
		{
			title = "Leurs terres",
			text = [=[Ils tiennent {link:stranglethorn-vale}la Vallée{/link} des Brisepierre et les collines du sud, où leur chef {link:grawmug}Grawmug{/link} occupe la grotte la plus profonde. Ils ont pris la plus grande île du Loch. Aux {link:ironband-s-excavation-site}Excavations d'Ironband{/link}, où ils surgirent parmi les ruines, un chef appelé Galgosh et un chaman tribal appelé Magosh règnent sur les fouilles. Leurs rangs comptent des éclaireurs, des cogne-crânes et des brise-os, ainsi que des voyants, des chamans et des géomanciens qui pratiquent une magie grossière de la terre.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les Brisepierre sont attirés par les idoles sculptées de l'excavation, et certains d'entre eux en deviennent fous furieux. Le prospecteur {link:prospector-ironband}Ironband{/link} espère que les idoles expliqueront un jour le lien entre les troggs et les titans. En attendant, les montagnards de la tour du sud les combattent avec le peu qu'ils ont. Ils comptent les troggs qu'ils tuent à leurs dents de pierre.]=],
		},
	},
})

