		},
		{
			title = "Leurs usages",
			text = [=[Ce sont des brutes, des exécuteurs et des chamans, avec des mystiques parmi eux, et ils suivent un chef appelé {link:chok-sul}Chok'sul{/link}. Ils extraient des cristaux dans leurs grottes, si rares que les nains doivent se battre pour un seul. Ils attaquent les routes du Loch, et on leur impute les attaques contre {link:thelsamar}Thelsamar{/link}, le {link:stonewrought-dam}Barrage de Formepierre{/link} et l'excavation. Ils tendirent un jour une embuscade à une caravane de minerai qui venait des {link:wetlands}Paluns{/link} vers Thelsamar et emportèrent le minerai dans leur camp.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le magistrat de {link:thelsamar}Thelsamar{/link} a engagé des mercenaires pour les briser, et la tête de {link:chok-sul}Chok'sul{/link} est mise à prix. Le magistrat veut régler d'abord le cas des ogres, afin que la ville puisse enfin se retourner contre les troggs.]=],
		},
	},
})

Translate("frFR", "tunnel-rat-kobolds", {
	title = "Kobolds Tunnel Rat",
	aliases = { "Tunnel Rats", "kobolds Tunnel Rat", "kobolds tunnel rat" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Tunnel Rats sont les {link:kobolds}kobolds{/link} du {link:loch-modan}Loch Modan{/link}. Ils se sont installés dans les contreforts à l'ouest de {link:thelsamar}Thelsamar{/link} et ont creusé leurs tanières à flanc de montagne, et ils ont pris l'ancienne {link:silver-stream-mine}Mine du Ru d'argent{/link}, au nord.]=],
		},
		{
			title = "Leurs usages",
			text = [=[Ce sont des creuseurs, des fourrageurs, des éclaireurs et des arpenteurs, et leurs géomanciens portent un goudron de feu que même les chamans du Loch trouvent utile. Dans la {link:silver-stream-mine}Mine du Ru d'argent{/link}, ils ont mis la patte sur les outils que la Ligue des mineurs y avait entreposés. Les montagnards ne demanderaient pas mieux que d'entrer et de les déloger, mais la Ligue veut d'abord que son matériel soit sauvé.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le montagnard {link:mountaineer-kadrell}Kadrell{/link} paie une prime pour leurs oreilles, et il en regrette l'odeur. Le montagnard {link:stormpike-guard}Stormpike{/link} attend l'ordre de nettoyer la mine.]=],
		},
	},
})
